#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Owner setup, M0 and first run (docs/PLAN.md §1, §10, §11, §14). Re-run any time: values
# already in .env are offered as defaults, and every action below is safe to repeat.
cd "$(dirname "$0")/.."
TS=$(command -v tailscale || echo /Applications/Tailscale.app/Contents/MacOS/Tailscale)

# put_env KEY VALUE [FILE]: KEY=VALUE in place, unquoted (apply-env.sh refuses quotes, spaces, $, \, `).
put_env() {
  local key="$1" value="$2" file="${3:-.env}" tmp
  if [[ "$value" == *[[:space:]\"\'\$\\\`]* ]]; then warn "$key not saved: no spaces, quotes, \$, \\ or backticks"; return 1; fi
  tmp=$(mktemp)
  awk -v k="$key" -v v="$value" 'index($0, k "=") == 1 { if (!d) print k "=" v; d = 1; next } { print } END { if (!d) print k "=" v }' "$file" > "$tmp"
  cat "$tmp" > "$file"; rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$file"
}
# ask_until KEY "Prompt" REGEX "hint": asks until the value matches (the same rules as apply-env.sh).
ask_until() {
  while :; do ask "$1" "$2"; [[ "${!1}" =~ $3 ]] && return; warn "$4"; done
}
# check "label" command...: one PASS/FAIL line.
check() {
  local label="$1"; shift
  if "$@" >/dev/null 2>&1; then printf '  %s✓ PASS%s %s\n' "$GREEN" "$RESET" "$label"
  else printf '  %s✗ FAIL%s %s\n' "$YELLOW" "$RESET" "$label"; SKIPPED+=("self-check failed: $label"); fi
}
no_env_files() { ! docker compose exec -T "$1" ls -a /data | grep -q '^\.env'; }
ollama_off_lan() { local ip; ip=$(ipconfig getifaddr en0 || ipconfig getifaddr en1); [[ -n "$ip" ]] && ! curl -s -m 3 "http://$ip:11434"; }
no_funnel() { [[ "$("$TS" serve status --json | jq '.AllowFunnel // {} | length')" == 0 ]]; }
all_healthy() { ! docker compose ps --format '{{.Health}}' | grep -qv '^healthy$'; }
copy_value() { awk -v k="$1" 'index($0, k "=") == 1 { printf "%s", substr($0, length(k) + 2) }' .env | pbcopy; }

TOTAL_STAGES=16

banner "ShortCircuit: owner setup (M0 + first run)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Settings files"
say "Makes .env and renderer.env from the examples (kept if they exist; both are git-ignored)."
[[ -f .env ]] || { (umask 077 && cp .env.example .env); note "made .env from .env.example"; }
[[ -f renderer.env ]] || { (umask 077 && cp renderer.env.example renderer.env); note "made renderer.env from renderer.env.example"; }
chmod 600 .env renderer.env
for k in N8N_ENCRYPTION_KEY POSTGRES_PASSWORD POSTGRES_APP_PASSWORD; do
  if [[ -z "$(_existing "$k" || true)" ]]; then
    n=24; [[ $k == N8N_ENCRYPTION_KEY ]] && n=32
    put_env "$k" "$(openssl rand -hex $n)"
  else note "$k already set (never change it after the first start, PLAN §1)"; fi
done
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Bot Gmail account"
say "A new free Gmail account only for ShortCircuit. It sends every mail and holds the Drive folder."
open_url "https://accounts.google.com/signup"
step "Make the account (any name). Keep its password in your password manager."
ask_until BOT_EMAIL "Bot Gmail address:" '^[^@,;[:space:]]+@[^@,;.[:space:]]+(\.[^@,;.[:space:]]+)+$' "one plain address"
put_env BOT_EMAIL "$BOT_EMAIL"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Owner, channel and time zone"
say "OWNER_EMAIL is the only address mail is ever sent to."
ask_until OWNER_EMAIL "Your own address:" '^[^@,;[:space:]]+@[^@,;.[:space:]]+(\.[^@,;.[:space:]]+)+$' "one plain address"
put_env OWNER_EMAIL "$OWNER_EMAIL"
say "Until go-live (M11) use a TEST channel: the M10 dry run runs on it. scripts/go-live.sh switches later."
step "Copy the handle exactly as the channel page shows it, with the @."
ask_until CHANNEL_HANDLE "Test channel handle:" '^@[A-Za-z0-9._-]{3,30}$' "looks like @handle (3-30 of A-Z a-z 0-9 . _ -)"
put_env CHANNEL_HANDLE "$CHANNEL_HANDLE"
ask_until TZ "Time zone (zoneinfo, e.g. Asia/Dhaka):" '^[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)*$' "a zone like Europe/London"
[[ -f /usr/share/zoneinfo/$TZ ]] && put_env TZ "$TZ" || warn "$TZ is not in /usr/share/zoneinfo; re-run this stage"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: private network for the forms"
say "Install Tailscale on this Mac AND your phone, log in to the same account on both."
open_url "https://tailscale.com/download/mac"
step "Install the Mac app, sign in, and set it to start at login (menu bar icon → Settings)."
step "Install Tailscale on your phone and sign in with the same account."
pause "Press Enter when both show Connected"
open_url "https://login.tailscale.com/admin/dns"
step "On the DNS page: MagicDNS on, and HTTPS Certificates → Enable."
pause "Press Enter when HTTPS certificates are enabled"
if dns=$("$TS" status --json 2>/dev/null | jq -er '.Self.DNSName'); then
  put_env WEBHOOK_URL "https://${dns%.}/"
  if confirm "Serve n8n to your tailnet only (tailscale serve, never funnel)?"; then
    "$TS" serve --bg --https=443 http://127.0.0.1:5678 && note "serving $WEBHOOK_URL inside the tailnet"
  fi
else
  warn "tailscale CLI not reachable; set WEBHOOK_URL=https://<mac>.<tailnet>.ts.net/ in .env by hand"
  SKIPPED+=("WEBHOOK_URL and tailscale serve")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Mac stays on"
say "Never sleep on power, boot after a power cut (PLAN §11). Needs your Mac password (sudo)."
if confirm "Run: sudo pmset -c sleep 0 disksleep 0 && sudo pmset autorestart 1 ?"; then
  sudo pmset -c sleep 0 disksleep 0 && sudo pmset autorestart 1 && note "power settings set"
else SKIPPED+=("pmset: sleep 0 / autorestart 1"); fi
step "System Settings → Users & Groups → Automatically log in as: you (not offered while FileVault is on)."
step "Docker Desktop → Settings → General: Start when you sign in. Resources: Memory 6 GB."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Ollama (local model, runs on the Mac, not in Docker)"
OLLAMA_MODEL=$(_existing OLLAMA_MODEL || echo qwen3:8b)
say "Starts Ollama at login, bound to 127.0.0.1 only. Never set OLLAMA_HOST=0.0.0.0."
if confirm "Run: brew services start ollama && ollama pull $OLLAMA_MODEL ?"; then
  brew services start ollama >/dev/null && sleep 2 && ollama pull "$OLLAMA_MODEL"
else SKIPPED+=("ollama start + pull $OLLAMA_MODEL"); fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: one project, three APIs"
say "Sign in as the BOT account ($BOT_EMAIL) for every Google page in this stage and the next."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project named ShortCircuit and select it."
open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
step "Enable (Gmail API)."
open_url "https://console.cloud.google.com/apis/library/drive.googleapis.com"
step "Enable (Google Drive API)."
open_url "https://console.cloud.google.com/apis/library/youtube.googleapis.com"
step "Enable (YouTube Data API v3)."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: consent screen and OAuth client"
open_url "https://console.cloud.google.com/auth/overview"
step "Get started: app name ShortCircuit, support e-mail = bot, audience External, contact = bot."
step "Audience → Publish app → status In production (Testing tokens die every 7 days)."
step "Clients → Create client → Web application."
step "Authorized redirect URI: ${WEBHOOK_URL:-https://<mac>.<tailnet>.ts.net/}rest/oauth2-credential/callback"
step "Create. Keep the client id and secret open: stage 13 pastes them into n8n (not into .env)."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Model keys: Gemini, Groq, Anthropic (they go into n8n credentials, stage 13)"
open_url "https://aistudio.google.com/apikey"
step "As the bot: Create API key. Keep it for stage 13."
open_url "https://console.groq.com/keys"
step "Create API key. Keep it for stage 13."
open_url "https://console.groq.com/docs/your-data"
step "Read whether Groq trains on API data; note the answer in docs/notes/m0.md (PLAN §4)."
step "Check each worker model's daily free limit is >= 60 a day; note it in docs/notes/m0.md."
open_url "https://console.anthropic.com/settings/keys"
step "Claude Console: create an API key (stage 13)."
open_url "https://console.anthropic.com/settings/limits"
step "Set a monthly spend limit (default plan: \$40)."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Pexels key (stock video, renderer only)"
open_url "https://www.pexels.com/api/"
step "Sign up / log in → Your API key → copy."
ask_secret PEXELS_API_KEY "Paste the Pexels key:"
put_env PEXELS_API_KEY "$PEXELS_API_KEY" renderer.env
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "YouTube API audit (needed for PUBLISH_MODE=auto, takes weeks)"
open_url "https://support.google.com/youtube/contact/yt_api_form"
step "Fill in the audit form for the ShortCircuit Cloud project. Until it passes, manual mode works."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Start the stack"
say "Checks .env (apply-env.sh), starts Docker, installs the .env watcher and the nightly backup."
bash scripts/apply-env.sh || true
if [[ "$(cat state/.env.applied.sha256 2>/dev/null)" == "$(shasum -a 256 < .env | cut -d' ' -f1)" ]]; then
  note ".env checked and applied (state/.env.live)"
  docker compose up -d
  note "waiting for every service to be healthy (up to 5 min)…"
  for _ in $(seq 60); do all_healthy && break; sleep 5; done
  docker compose ps --format '  {{.Service}}: {{.Health}}'
  for a in apply-env backup; do
    p=~/Library/LaunchAgents/com.shortcircuit.$a.plist
    sed "s|__ROOT__|$PWD|g" "launchd/com.shortcircuit.$a.plist" > "$p"
    launchctl bootout "gui/$(id -u)/com.shortcircuit.$a" 2>/dev/null || true
    launchctl bootstrap "gui/$(id -u)" "$p" && note "launchd agent com.shortcircuit.$a installed"
  done
else
  warn ".env not applied: refused (the line above says why) or Docker not running. Fix, then re-run."
  SKIPPED+=("stack start: .env not applied")
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "n8n: owner account, licence, workflows, credentials"
open_url "${WEBHOOK_URL:-http://127.0.0.1:5678/}"
step "Make the owner account with a LONG password (anyone on the tailnet sees this login)."
step "Settings → Usage and plan: register the free community edition, paste the key it mails you."
pause "Press Enter when you are logged in"
bash scripts/import-workflows.sh || SKIPPED+=("import-workflows.sh failed: re-run it")
open_url "${WEBHOOK_URL:-http://127.0.0.1:5678/}home/credentials"
say "Fill in each credential (PLAN §10.2):"
step "Gmail Bot, Drive Bot: the OAuth client id/secret (stage 8); Connect, signed in as the bot."
step "YouTube Channel: same client; Connect as the account that owns the TEST channel."
step "Gemini, Groq: the keys from stage 9. Ollama: base URL http://host.docker.internal:11434."
step "Anthropic: the Console key. Anthropic Header: name x-api-key, value the same key."
copy_value POSTGRES_APP_PASSWORD && step "SC Postgres: host postgres, db shortcircuit, user sc_app, password = clipboard (copied)."
pause "Press Enter for the cancel-form password"
openssl rand -hex 16 | tr -d '\n' | pbcopy
step "SC Cancel Form: user owner, password = clipboard (new random). Save it in your password manager."
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "First runs in n8n"
step "Open sc.config → Execute workflow (makes the Drive folder, shares it with you)."
step "Open sc.fixtures → Execute workflow (loads tests/agents/ into the eval_* Data Tables)."
step "In each sc.eval.<agent>: open the Evaluation Trigger, pick table eval_<agent>, save."
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Music (and optional brand)"
say "sc.render stops until assets/music/ has at least one mood folder. Add tracks by hand."
open_url "https://studio.youtube.com"
step "Studio → Audio library: download tracks marked no attribution needed."
mkdir -p assets/music/upbeat assets/music/calm assets/brand
open assets/music >/dev/null 2>&1 || true
step "Put them in assets/music/upbeat/ and assets/music/calm/ (any folder name is a mood)."
step "Optional: assets/brand/font.ttf and assets/brand/card.png (1080x1920)."
pause "Press Enter when the tracks are in place"
note "$(find assets/music -type f \( -iname '*.mp3' -o -iname '*.wav' -o -iname '*.m4a' -o -iname '*.ogg' -o -iname '*.flac' -o -iname '*.aac' \) | wc -l | tr -d ' ') track(s) found"

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Self-checks (M0 done-when)"
check ".env and renderer.env are git-ignored" git check-ignore -q .env renderer.env
check "all containers healthy" all_healthy
check "no .env file visible in the renderer's /data" no_env_files renderer
check "no .env file visible in n8n's /data" no_env_files n8n
check "Ollama does not answer on the LAN address" ollama_off_lan
check "Ollama answers on 127.0.0.1" curl -sf -m 3 http://127.0.0.1:11434
check "tailscale funnel is off" no_funnel
check "n8n answers on the tailnet URL" curl -sf -m 5 "${WEBHOOK_URL:-https://invalid/}healthz"
say ""
step "On your phone: open ${WEBHOOK_URL:-the tailnet URL} with Tailscale on (works) and off on cellular (fails)."
step "Copy .env and renderer.env into your password manager (N8N_ENCRYPTION_KEY: lose it, lose every credential)."
pause

finish
note "Next: the live checks of M1–M9 (docs/PLAN.md §14, the rows docs/notes/build.md lists as not checked),"
note "then M10 with REVIEW_HOURS=1 in .env for the 7-day dry run, then: bash scripts/go-live.sh"
printf '\n'
}

run_wizard "$@"; exit
